Colour sourceColour(int n){constexpr uint32_t colours[]{0xff4fe3f5,0xff6cf2b8,0xffff6ad5,0xff8f7bff,0xff67a8ff,0xffffc876};return Colour(colours[size_t(std::max(0,n-1)%6)]);}
void card(Graphics& g,Rectangle<float> area,Colour accent){g.setGradientFill(ColourGradient(Colour(0xff1b2442),area.getTopLeft(),Colour(0xff11182c),area.getBottomRight(),false));g.fillRoundedRectangle(area,14);g.setColour(Colours::white.withAlpha(.1f));g.drawRoundedRectangle(area.reduced(.5f),14,1);if(!accent.isTransparent()){g.setColour(accent.withAlpha(.65f));g.fillRoundedRectangle(area.getX()+14,area.getY()+13,3,13,1.5f);}}
Style::Style(PrismProcessor& p):processor(p){setColour(ComboBox::backgroundColourId,Colour(0xff10182c));setColour(ComboBox::outlineColourId,Colours::white.withAlpha(.13f));setColour(ComboBox::textColourId,ice());setColour(ComboBox::arrowColourId,aqua());setColour(PopupMenu::backgroundColourId,Colour(0xff131a2e));setColour(PopupMenu::textColourId,ice());setColour(PopupMenu::highlightedBackgroundColourId,Colour(0xff324665));setColour(TextButton::buttonColourId,Colour(0xff222d4c));setColour(TextButton::buttonOnColourId,Colour(0xff3c4784));setColour(TextButton::textColourOffId,ice());setColour(Label::textColourId,ice());setColour(TextEditor::backgroundColourId,Colour(0xff10182c));setColour(TextEditor::outlineColourId,Colours::white.withAlpha(.13f));setColour(TextEditor::textColourId,ice());setColour(Slider::textBoxTextColourId,ice());setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);setColour(Slider::textBoxBackgroundColourId,Colours::transparentBlack);setColour(TooltipWindow::backgroundColourId,Colour(0xff1b2442));setColour(TooltipWindow::textColourId,ice());}
Label* Style::createSliderTextBox(Slider& s){auto* label=LookAndFeel_V4::createSliderTextBox(s);label->setFont(FontOptions(9.f));label->setColour(Label::outlineColourId,Colours::transparentBlack);label->setColour(Label::textColourId,ice());return label;}
void Style::drawRotarySlider(Graphics& g,int x,int y,int width,int height,float value,float first,float last,Slider& slider){
 float radius=float(std::min(width,height))*.5f-6,cx=float(x+width/2),cy=float(y+height/2);Colour colour=aqua();int index=int(slider.getProperties()["parameter"]);const auto& schema=SynthB::Schema::get();if(index==schema.loc.euphoria)colour=Colour(0xffff6ad5);if(index==schema.loc.space)colour=violet();
 auto arc=[&](float r,float start,float end,Colour c,float thickness){Path path;path.addCentredArc(cx,cy,r,r,0,start,end,true);g.setColour(c);g.strokePath(path,PathStrokeType(thickness,PathStrokeType::curved,PathStrokeType::rounded));};
 arc(radius,first,last,Colours::white.withAlpha(.11f),2);arc(radius,first,first+value*(last-first),colour.withAlpha(.13f),5);arc(radius,first,first+value*(last-first),colour,2);
 float angle=first+(last-first)*value;g.setColour(colour);g.fillEllipse(cx+std::sin(angle)*radius-2,cy-std::cos(angle)*radius-2,4,4);
 for(int r=0;r<SynthB::routes;++r){int base=schema.loc.route[r];int src=int(processor.read(base));if(src>0&&int(processor.read(base+1))==index+1){float depth=processor.read(base+2);float a=std::max(0.f,value-(processor.read(base+3)>.5f?std::abs(depth):0)),b=std::min(1.f,value+std::abs(depth));Colour modulation=sourceColour(src);arc(radius+4,first+a*(last-first),first+b*(last-first),modulation.withAlpha(.75f),1.4f);float shown=schema.specs[size_t(index)].unitValue(processor.engine.displayed[size_t(index)].load());float at=first+shown*(last-first);g.setColour(modulation);g.fillEllipse(cx+std::sin(at)*(radius+4)-1.8f,cy-std::cos(at)*(radius+4)-1.8f,3.6f,3.6f);break;}}
}
void Style::drawLinearSlider(Graphics& g,int x,int y,int w,int h,float at,float,float,Slider::SliderStyle shape,Slider&){g.setColour(Colours::white.withAlpha(.1f));if(shape==Slider::LinearVertical){float middle=float(x+w/2);g.fillRoundedRectangle(middle-2,float(y),4,float(h),2);g.setColour(aqua().withAlpha(.6f));g.fillRoundedRectangle(middle-2,at,4,float(y+h)-at,2);g.setColour(ice());g.fillRoundedRectangle(middle-6,at-2,12,4,2);}else{float middle=float(y+h/2);g.fillRoundedRectangle(float(x),middle-2,float(w),4,2);g.setColour(aqua());g.fillRoundedRectangle(float(x),middle-2,std::max(1.f,at-float(x)),4,2);g.setColour(ice());g.fillEllipse(at-3,middle-3,6,6);}}
void Style::drawToggleButton(Graphics& g,ToggleButton& b,bool,bool){auto r=b.getLocalBounds().toFloat();g.setColour(b.getToggleState()?aqua().withAlpha(.2f):Colours::white.withAlpha(.06f));g.fillRoundedRectangle(r,7);g.setColour(b.getToggleState()?aqua():Colour(0xff6c7892));g.fillEllipse(5,r.getCentreY()-2.5f,5,5);g.setColour(ice());g.setFont(FontOptions(9.f));g.drawText(b.getButtonText(),b.getLocalBounds().withTrimmedLeft(15),Justification::centredLeft);}
Dial::Dial(PrismProcessor& p,Style& look,int index,bool linear,bool row):parameter(index),processor(p),linear(linear),row(row){
 setLookAndFeel(&look);const auto& spec=SynthB::Schema::get().specs[size_t(index)];label.setText(spec.title,dontSendNotification);label.setFont(FontOptions(row?11.f:9.f));label.setColour(Label::textColourId,Colour(0xffa9b7d3));label.setJustificationType(row?Justification::centredLeft:Justification::centred);addAndMakeVisible(label);
 if(!spec.options.empty()){choice.setLookAndFeel(&look);for(size_t i=0;i<spec.options.size();++i)choice.addItem(spec.options[i],int(i+1));addAndMakeVisible(choice);menuBinding=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(processor.parameters,spec.key,choice);choice.setTooltip(spec.key);}
 else {slider.setLookAndFeel(&look);slider.getProperties().set("parameter",index);slider.setSliderStyle(row?Slider::LinearHorizontal:linear?Slider::LinearVertical:Slider::RotaryVerticalDrag);slider.setTextBoxStyle(Slider::TextBoxBelow,false,row?70:54,12);slider.setRotaryParameters(float(SynthB::tau*.625),float(SynthB::tau*1.375),true);slider.setMouseDragSensitivity(170);slider.setVelocityModeParameters(.2,1,0,true,ModifierKeys::shiftModifier);slider.setPopupMenuEnabled(false);addAndMakeVisible(slider);binding=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(processor.parameters,spec.key,slider);
  slider.textFromValueFunction=[spec](double value){if(spec.unit=="s")return value<1?String(value*1000,0)+"ms":String(value,2)+"s";if(value>=1000&&spec.low>=0)return String(value/1000,2)+"k";return String(value,spec.integer?0:spec.high>100?1:2);};slider.valueFromTextFunction=[spec](const String& text){double v=text.getDoubleValue();if(text.containsIgnoreCase("k"))v*=1000;if(spec.unit=="s"&&text.containsIgnoreCase("ms"))v/=1000;return v;};slider.setTextValueSuffix("");slider.updateText();slider.setTooltip(spec.key+" • Drag a source here • Shift: fine • Double-click: reset");slider.addMouseListener(this,false);
 }
 label.addMouseListener(this,false);
}
Dial::~Dial(){slider.removeMouseListener(this);label.removeMouseListener(this);slider.setLookAndFeel(nullptr);choice.setLookAndFeel(nullptr);setLookAndFeel(nullptr);}
void Dial::resized(){auto r=getLocalBounds();if(row){label.setBounds(r.removeFromLeft(getWidth()/2));if(menuBinding)choice.setBounds(r.reduced(3));else slider.setBounds(r);}else{label.setBounds(r.removeFromTop(13));if(menuBinding)choice.setBounds(r.reduced(1));else slider.setBounds(r);}}
void Dial::paint(Graphics& g){if(hover){g.setColour(aqua().withAlpha(.14f));g.fillRoundedRectangle(getLocalBounds().toFloat(),9);g.setColour(aqua());g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(.7f),9,1.4f);}}
bool Dial::isInterestedInDragSource(const SourceDetails& d){return d.description.toString().startsWith("mod:");}
void Dial::itemDragEnter(const SourceDetails&){hover=true;repaint();}void Dial::itemDragExit(const SourceDetails&){hover=false;repaint();}
void Dial::itemDropped(const SourceDetails& details){hover=false;int source=details.description.toString().fromFirstOccurrenceOf(":",false,false).getIntValue();processor.route(source,parameter);repaint();}
void Dial::mouseDown(const MouseEvent& event){
 const auto& schema=SynthB::Schema::get();int first=-1;for(int i=0;i<SynthB::routes;++i)if(processor.read(schema.loc.route[i])>0&&int(processor.read(schema.loc.route[i]+1))==parameter+1){first=i;break;}
 auto relative=event.getEventRelativeTo(&slider);bool ring=!linear&&!row&&relative.position.getDistanceFrom(Point<float>(float(slider.getWidth())*.5f,float(slider.getHeight()-12)*.5f))>float(std::min(slider.getWidth(),slider.getHeight()-12))*.38f;
 if(first>=0&&ring&&!event.mods.isPopupMenu()&&event.eventComponent==&slider){if(inspect)inspect("mod"+String(first+1)+".");return;}
 if(!event.mods.isPopupMenu())return;PopupMenu menu;menu.addItem(1,"Learn MIDI CC");menu.addItem(2,"Remove MIDI CC");menu.addItem(3,"Reset");if(first>=0){menu.addItem(4,"Edit modulation depth / bipolar / curve");menu.addItem(5,"Remove modulation routes");}
 Component::SafePointer<Dial> safe(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(this),[safe,first](int result){if(!safe)return;if(result==1)safe->processor.learnTarget.store(safe->parameter);if(result==2)for(auto& cc:safe->processor.ccAssignments)if(cc.load()==safe->parameter)cc.store(-1);if(result==3)safe->processor.write(safe->parameter,SynthB::Schema::get().specs[size_t(safe->parameter)].initial);if(result==4&&safe->inspect)safe->inspect("mod"+String(first+1)+".");if(result==5)for(int base:SynthB::Schema::get().loc.route)if(int(safe->processor.read(base+1))==safe->parameter+1)safe->processor.write(base,0);});
}
void SourceChip::paint(Graphics& g){auto colour=sourceColour(source);g.setColour(colour.withAlpha(.12f));g.fillRoundedRectangle(getLocalBounds().toFloat(),8);g.setColour(colour.withAlpha(.4f));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(.5f),8,1);g.setColour(colour);g.setFont(FontOptions(9.f,Font::bold));g.drawText(label,getLocalBounds(),Justification::centred);}
void SourceChip::mouseDrag(const MouseEvent& e){if(e.getDistanceFromDragStart()>3)if(auto* drag=DragAndDropContainer::findParentDragContainerFor(this))drag->startDragging("mod:"+String(source),this);}
void WaveView::paint(Graphics& g){
 int base=SynthB::Schema::get().loc.osc[oscillator];const auto& table=SynthB::Tables::get().at(int(processor.read(base)),processor.importedTable());float position=processor.voices.load()>0?processor.engine.displayed[size_t(base+SynthB::pos)].load():processor.read(base+SynthB::pos);g.setColour(Colour(0xff0d1528));g.fillRoundedRectangle(getLocalBounds().toFloat(),9);
 const float w=float(getWidth()-30),h=float(getHeight()-26);for(int frame=13;frame>=0;--frame){float p=float(frame)/13,offset=float(frame)*1.6f;Path path;for(int n=0;n<100;++n){float x=9+float(n)*w/99+offset*.6f,y=h*.6f+18-offset+table.visual(float(n)/100,p)*h*.24f;if(n==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.setColour((oscillator==0?aqua():violet()).withAlpha(.1f+.15f*(1-p)));g.strokePath(path,PathStrokeType(.7f));}
 Path active;for(int n=0;n<160;++n){float x=9+float(n)*w/159+position*13*.96f,y=h*.6f+18-position*13*1.6f+table.visual(float(n)/160,position)*h*.24f;if(n==0)active.startNewSubPath(x,y);else active.lineTo(x,y);}auto colour=oscillator==0?aqua():violet();g.setColour(colour.withAlpha(.15f));g.strokePath(active,PathStrokeType(4));g.setColour(colour);g.strokePath(active,PathStrokeType(1.4f));
 int voices=int(processor.read(base+SynthB::unison));g.setColour(colour.withAlpha(.65f));for(int i=0;i<voices;++i)g.fillEllipse(float(getWidth()/2)+(float(i)-float(voices-1)*.5f)*5-1.5f,float(getHeight()-7),3,3);
}
void FilterView::paint(Graphics& g){int b=SynthB::Schema::get().loc.filter[filter];float cutoff=processor.read(b+SynthB::cutoff),res=processor.read(b+SynthB::resonance);int type=int(processor.read(b+SynthB::type));g.setColour(Colours::white.withAlpha(.04f));for(int y=10;y<getHeight();y+=12)g.drawHorizontalLine(y,0,float(getWidth()));Path path;
 for(int i=0;i<getWidth();++i){float hz=20*std::pow(1000.f,float(i)/float(getWidth())),r=hz/cutoff,m=1/std::sqrt(1+std::pow(r,type==1?8.f:4.f));if(type==2)m=1-m;if(type==3)m=std::exp(-std::pow(std::log2(r)*1.6f,2.f));if(type==4)m=1-std::exp(-std::pow(std::log2(r)*2,2.f));if(type==5)m=.45f+.45f*std::cos(float(SynthB::tau)*r);if(type==6)m=.2f+.8f*std::exp(-std::pow((std::log2(hz)-10.5f),2.f));if(type>=7)m=.4f+.4f*(type==7?1-m:m);m+=res*.2f*std::exp(-std::pow(std::log2(r)*3,2.f));float y=float(getHeight()-3)-m*float(getHeight()-8);if(i==0)path.startNewSubPath(0,y);else path.lineTo(float(i),y);}
 g.setColour(filter==0?aqua():violet());g.strokePath(path,PathStrokeType(1.3f));float x=std::log(cutoff/20)/std::log(1000.f)*float(getWidth());g.fillEllipse(x-3,3,6,6);
}
void FilterView::mouseDrag(const MouseEvent& e){int b=SynthB::Schema::get().loc.filter[filter];processor.write(b+SynthB::cutoff,20*std::pow(1000.f,SynthB::bounded(float(e.x)/float(getWidth()),0.f,1.f)));processor.write(b+SynthB::resonance,SynthB::bounded(1-float(e.y)/float(getHeight()),0.f,1.f));repaint();}
DetailView::DetailView(PrismProcessor& processor,Style& style,String query){setLookAndFeel(&style);addAndMakeVisible(search);search.setTextToShowWhenEmpty("Search every parameter, section or ID",Colour(0xff6e809f));search.setText(query);addAndMakeVisible(viewport);viewport.setViewedComponent(&rows,false);const auto& specs=SynthB::Schema::get().specs;
 for(size_t i=0;i<specs.size();++i){auto control=std::make_unique<Dial>(processor,style,int(i),false,true);control->label.setText(specs[i].section+" / "+specs[i].title+"  ["+specs[i].key+"]",dontSendNotification);rows.addAndMakeVisible(*control);controls.push_back(std::move(control));}search.onTextChange=[this]{apply();};setSize(820,620);}
void DetailView::resized(){search.setBounds(12,12,getWidth()-24,28);viewport.setBounds(8,48,getWidth()-16,getHeight()-56);apply();}
void DetailView::apply(){String query=search.getText().trim();int y=0;for(auto& c:controls){const auto& spec=SynthB::Schema::get().specs[size_t(c->parameter)];bool show=query.isEmpty()||String(spec.key+" "+spec.section+" "+spec.title).containsIgnoreCase(query);c->setVisible(show);if(show){c->setBounds(8,y,std::max(660,viewport.getWidth()-30),38);y+=40;}}rows.setSize(std::max(680,viewport.getWidth()-20),y);}
Dial& Surface::dial(String id,int x,int y,int w,int h){int index=SynthB::Schema::get().find(id.toStdString());jassert(index>=0);auto c=std::make_unique<Dial>(processor,style,index);c->setBounds(x,y,w,h);c->inspect=[this](String q){showDetail(q);};addAndMakeVisible(*c);controls.push_back(std::move(c));return *controls.back();}
